// Generic scaler: input -> 15-bit intermediate -> horizontal filter -> vertical
// filter -> output, mirroring FFmpeg's swscale C pipeline.
const std = @import("std");
const m = @import("main.zig");
const y2r = @import("yuv2rgb.zig");
const alloc = std.heap.c_allocator;

fn roundedDiv(a: i64, b: i64) i64 {
    return if (a >= 0) @divTrunc(a + (b >> 1), b) else @divTrunc(a - (b >> 1), b);
}

// BT.601 coefficients (ff_yuv2rgb_coeffs[SWS_CS_DEFAULT]).
const coeffs = [4]i64{ 104597, 132201, 25675, 53279 };

pub const rgb2yuv: [9]i32 = blk: {
    @setEvalBranchQuota(10000);
    const vr = coeffs[0];
    const ub = coeffs[1];
    const ug = -coeffs[2];
    const vg = -coeffs[3];
    const ONE: i64 = 65536;
    const cy: i64 = @divTrunc(ONE * 255, 219);
    const W = roundedDiv(ONE * ONE * ug, ub);
    const V = roundedDiv(ONE * ONE * vg, vr);
    const Z = ONE * ONE - W - V;
    const Cy = roundedDiv(cy * Z, ONE);
    const Cu = roundedDiv(ub * Z, ONE);
    const Cv = roundedDiv(vr * Z, ONE);
    const S: i64 = 1 << 15;
    break :blk .{
        @intCast(-roundedDiv(S * V, Cy)),
        @intCast(roundedDiv(S * ONE * ONE, Cy)),
        @intCast(-roundedDiv(S * W, Cy)),
        @intCast(roundedDiv(S * V, Cu)),
        @intCast(-roundedDiv(S * ONE * ONE, Cu)),
        @intCast(roundedDiv(S * (Z + W), Cu)),
        @intCast(roundedDiv(S * (V + Z), Cv)),
        @intCast(-roundedDiv(S * ONE * ONE, Cv)),
        @intCast(roundedDiv(S * W, Cv)),
    };
};

fn roundToInt16(f: i64) i32 {
    const r: i64 = (f + (1 << 15)) >> 16;
    if (r < -0x7FFF) return -0x8000;
    if (r > 0x7FFF) return 0x7FFF;
    return @intCast(r);
}

// yuv2rgb "full" output coefficients (ff_yuv2rgb_c_init_tables, limited range).
pub const full = blk: {
    var cy: i64 = @divTrunc((1 << 16) * 255, 219);
    const oy: i64 = 16 << 16;
    var crv: i64 = @divTrunc(coeffs[0] * 224, 255);
    var cbu: i64 = @divTrunc(coeffs[1] * 224, 255);
    var cgu: i64 = @divTrunc(-coeffs[2] * 224, 255);
    var cgv: i64 = @divTrunc(-coeffs[3] * 224, 255);
    cy = (cy * 65536) >> 16;
    crv = (crv * 65536 * 65536) >> 32;
    cbu = (cbu * 65536 * 65536) >> 32;
    cgu = (cgu * 65536 * 65536) >> 32;
    cgv = (cgv * 65536 * 65536) >> 32;
    break :blk .{
        .y_coeff = roundToInt16(cy * (1 << 13)),
        .y_offset = roundToInt16(oy * (1 << 9)),
        .v2r = roundToInt16(crv * (1 << 13)),
        .v2g = roundToInt16(cgv * (1 << 13)),
        .u2g = roundToInt16(cgu * (1 << 13)),
        .u2b = roundToInt16(cbu * (1 << 13)),
    };
};

pub const Filter = struct {
    pos: []i32,
    coef: []i16,
    size: usize,
    n: usize,
    fn deinit(f: *Filter) void {
        alloc.free(f.pos);
        alloc.free(f.coef);
    }
};

fn ilog2(v: i64) i64 {
    if (v <= 0) return 0;
    return 63 - @as(i64, @clz(@as(u64, @intCast(v))));
}

// Port of FFmpeg initFilter for POINT / BILINEAR / BICUBIC, filterAlign = 1.
pub fn initFilter(xInc: i64, srcW: i64, dstW: i64, one: i64, algo: c_int, srcPos: i64, dstPos: i64) !Filter {
    const fone: i64 = @as(i64, 1) << @intCast(54 - @min(ilog2(@divTrunc(srcW, dstW)), 8));
    const n: usize = @intCast(dstW);
    const pos = try alloc.alloc(i32, n);
    errdefer alloc.free(pos);
    var filterSize: i64 = 1;
    var filter: []i64 = undefined;

    if (@abs(xInc - 0x10000) < 10 and srcPos == dstPos) {
        filterSize = 1;
        filter = try alloc.alloc(i64, n);
        for (0..n) |i| {
            filter[i] = fone;
            pos[i] = @intCast(i);
        }
    } else if (algo == 0) {
        filterSize = 1;
        filter = try alloc.alloc(i64, n);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 8) - ((srcPos * 0x8000) >> 7);
        for (0..n) |i| {
            const xx = (xDstInSrc - ((filterSize - 1) << 15) + (1 << 15)) >> 16;
            pos[i] = @intCast(xx);
            filter[i] = fone;
            xDstInSrc += xInc;
        }
    } else {
        const sizeFactor: i64 = if (algo == 2) 4 else 2;
        if (xInc <= 1 << 16) {
            filterSize = 1 + sizeFactor;
        } else {
            filterSize = 1 + @divTrunc(sizeFactor * srcW + dstW - 1, dstW);
        }
        filterSize = @min(filterSize, srcW - 2);
        filterSize = @max(filterSize, 1);
        const fs: usize = @intCast(filterSize);
        filter = try alloc.alloc(i64, n * fs);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 7) - ((srcPos * 0x10000) >> 7);
        for (0..n) |i| {
            var xx: i64 = @divTrunc(xDstInSrc - (filterSize - 2) * (1 << 16), 1 << 17);
            pos[i] = @intCast(xx);
            for (0..fs) |j| {
                var d: i64 = @as(i64, @intCast(@abs(xx * (1 << 17) - xDstInSrc))) << 13;
                var coeff: i64 = 0;
                if (xInc > 1 << 16) d = @divTrunc(d * dstW, srcW);
                if (algo == 2) {
                    const B: i64 = 0;
                    const C: i64 = @intFromFloat(0.6 * @as(f64, 1 << 24));
                    if (d >= @as(i64, 1) << 31) {
                        coeff = 0;
                    } else {
                        const dd = (d * d) >> 30;
                        const ddd = (dd * d) >> 30;
                        if (d < @as(i64, 1) << 30) {
                            coeff = (12 * (1 << 24) - 9 * B - 6 * C) * ddd +
                                (-18 * (1 << 24) + 12 * B + 6 * C) * dd +
                                (6 * (1 << 24) - 2 * B) * (1 << 30);
                        } else {
                            coeff = (-B - 6 * C) * ddd +
                                (6 * B + 30 * C) * dd +
                                (-12 * B - 48 * C) * d +
                                (8 * B + 24 * C) * (1 << 30);
                        }
                    }
                    coeff = @divTrunc(coeff, @divTrunc(@as(i64, 1) << 54, fone));
                } else {
                    coeff = (1 << 30) - d;
                    if (coeff < 0) coeff = 0;
                    coeff *= fone >> 30;
                }
                filter[i * fs + j] = coeff;
                xx += 1;
            }
            xDstInSrc += 2 * xInc;
        }
    }
    defer alloc.free(filter);

    // filter2 == filter (no src/dst vectors); reduce size
    const f2s: usize = @intCast(filterSize);
    var minFilterSize: usize = 0;
    var ii: isize = @as(isize, @intCast(n)) - 1;
    const cutoffLimit: f64 = 0.002 * @as(f64, @floatFromInt(fone));
    while (ii >= 0) : (ii -= 1) {
        const i: usize = @intCast(ii);
        var min: usize = f2s;
        var cutOff: i64 = 0;
        var j: usize = 0;
        while (j < f2s) : (j += 1) {
            cutOff += @intCast(@abs(filter[i * f2s]));
            if (@as(f64, @floatFromInt(cutOff)) > cutoffLimit) break;
            if (i < n - 1 and pos[i] >= pos[i + 1]) break;
            var k: usize = 1;
            while (k < f2s) : (k += 1) filter[i * f2s + k - 1] = filter[i * f2s + k];
            filter[i * f2s + k - 1] = 0;
            pos[i] += 1;
        }
        cutOff = 0;
        var jj: usize = f2s - 1;
        while (jj > 0) : (jj -= 1) {
            cutOff += @intCast(@abs(filter[i * f2s + jj]));
            if (@as(f64, @floatFromInt(cutOff)) > cutoffLimit) break;
            min -= 1;
        }
        if (min > minFilterSize) minFilterSize = min;
    }
    const fsz: usize = minFilterSize;
    const nf = try alloc.alloc(i64, n * fsz);
    defer alloc.free(nf);
    for (0..n) |i| {
        for (0..fsz) |j| {
            nf[i * fsz + j] = if (j >= f2s) 0 else filter[i * f2s + j];
        }
    }
    const sw: i32 = @intCast(srcW);
    const fszi: i32 = @intCast(fsz);
    for (0..n) |i| {
        if (pos[i] < 0) {
            var j: usize = 1;
            while (j < fsz) : (j += 1) {
                const left: usize = @intCast(@max(@as(i32, @intCast(j)) + pos[i], 0));
                nf[i * fsz + left] += nf[i * fsz + j];
                nf[i * fsz + j] = 0;
            }
            pos[i] = 0;
        }
        if (pos[i] + fszi > sw) {
            const shift: i32 = pos[i] + @min(fszi - sw, 0);
            var acc: i64 = 0;
            var j: isize = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (pos[i] + @as(i32, @intCast(j)) >= sw) {
                    acc += nf[i * fsz + ju];
                    nf[i * fsz + ju] = 0;
                }
            }
            j = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (j < shift) {
                    nf[i * fsz + ju] = 0;
                } else {
                    nf[i * fsz + ju] = nf[i * fsz + ju - @as(usize, @intCast(shift))];
                }
            }
            pos[i] -= shift;
            nf[i * fsz + @as(usize, @intCast(sw - 1 - pos[i]))] += acc;
        }
    }
    const coef = try alloc.alloc(i16, n * fsz);
    for (0..n) |i| {
        var err: i64 = 0;
        var sum: i64 = 0;
        for (0..fsz) |j| sum += nf[i * fsz + j];
        sum = @divTrunc(sum + @divTrunc(one, 2), one);
        if (sum == 0) sum = 1;
        for (0..fsz) |j| {
            const v = nf[i * fsz + j] + err;
            const intV = roundedDiv(v, sum);
            coef[i * fsz + j] = @intCast(intV);
            err = v - intV * sum;
        }
    }
    return .{ .pos = pos, .coef = coef, .size = fsz, .n = n };
}

fn isRGB(f: c_int) bool {
    return f >= m.RGB24 and f <= m.BGRA;
}

fn subH(f: c_int) u5 {
    return switch (f) {
        m.YUV420P, m.YUV422P, m.NV12, m.NV21 => 1,
        else => 0,
    };
}
fn subV(f: c_int) u5 {
    return switch (f) {
        m.YUV420P, m.NV12, m.NV21 => 1,
        else => 0,
    };
}

inline fn rowc(p: [*]const u8, stride: isize, y: usize) [*]const u8 {
    return p + @as(usize, @bitCast(stride * @as(isize, @intCast(y))));
}
inline fn rowm(p: [*]u8, stride: isize, y: usize) [*]u8 {
    return p + @as(usize, @bitCast(stride * @as(isize, @intCast(y))));
}

inline fn clip8(v: i32) u8 {
    return @intCast(std.math.clamp(v, 0, 255));
}

const RgbL = struct { bpp: usize, r: usize, g: usize, b: usize, a: usize };
fn rgbLayout(f: c_int) RgbL {
    return switch (f) {
        m.RGB24 => .{ .bpp = 3, .r = 0, .g = 1, .b = 2, .a = 0 },
        m.BGR24 => .{ .bpp = 3, .r = 2, .g = 1, .b = 0, .a = 0 },
        m.RGBA => .{ .bpp = 4, .r = 0, .g = 1, .b = 2, .a = 3 },
        else => .{ .bpp = 4, .r = 2, .g = 1, .b = 0, .a = 3 },
    };
}

pub const Generic = struct {
    sw: usize,
    sh: usize,
    dw: usize,
    dh: usize,
    sf: c_int,
    df: c_int,
    chrSrcW: usize,
    chrSrcH: usize,
    chrDstW: usize,
    chrDstH: usize,
    chrSrcHSub: u5,
    chrSrcVSub: u5,
    fullChr: bool,
    needAlpha: bool,
    doChroma: bool,
    hLum: Filter,
    vLum: Filter,
    hChr: Filter,
    vChr: Filter,
    // horizontally scaled planes
    lum: []i16,
    chrU: []i16,
    chrV: []i16,
    alp: []i16,
    lumNeed: []bool,
    chrNeed: []bool,
    tmp16: []u16,
    tmpU16: []u16,
    tmpV16: []u16,
    tmpA16: []u16,
    tmpU8: []u8,
    tmpV8: []u8,

    pub fn init(sw: usize, sh: usize, sf: c_int, dw: usize, dh: usize, df: c_int, algo: c_int) !*Generic {
        const g = try alloc.create(Generic);
        errdefer alloc.destroy(g);
        g.sw = sw;
        g.sh = sh;
        g.dw = dw;
        g.dh = dh;
        g.sf = sf;
        g.df = df;
        var chrSrcHSub = subH(sf);
        const chrSrcVSub = subV(sf);
        var chrDstHSub = subH(df);
        const chrDstVSub = subV(df);
        var fullChr = false;
        if (isRGB(df)) {
            if ((dw & 1) != 0) fullChr = true;
            if (chrSrcHSub == 0 and chrSrcVSub == 0) fullChr = true;
            if (!fullChr) chrDstHSub = 1;
        }
        if (isRGB(sf) and ((dw >> chrDstHSub) <= (sw >> 1))) chrSrcHSub = 1;
        g.chrSrcHSub = chrSrcHSub;
        g.chrSrcVSub = chrSrcVSub;
        g.fullChr = fullChr;
        g.chrSrcW = (sw + (@as(usize, 1) << chrSrcHSub) - 1) >> chrSrcHSub;
        g.chrSrcH = (sh + (@as(usize, 1) << chrSrcVSub) - 1) >> chrSrcVSub;
        g.chrDstW = (dw + (@as(usize, 1) << chrDstHSub) - 1) >> chrDstHSub;
        g.chrDstH = (dh + (@as(usize, 1) << chrDstVSub) - 1) >> chrDstVSub;
        g.needAlpha = (sf == m.RGBA or sf == m.BGRA) and (df == m.RGBA or df == m.BGRA);
        g.doChroma = df != m.GRAY8;

        const swi: i64 = @intCast(sw);
        const shi: i64 = @intCast(sh);
        const dwi: i64 = @intCast(dw);
        const dhi: i64 = @intCast(dh);
        const lumXInc = @divTrunc((swi << 16) + (dwi >> 1), dwi);
        const lumYInc = @divTrunc((shi << 16) + (dhi >> 1), dhi);
        const csw: i64 = @intCast(g.chrSrcW);
        const csh: i64 = @intCast(g.chrSrcH);
        const cdw: i64 = @intCast(g.chrDstW);
        const cdh: i64 = @intCast(g.chrDstH);
        const chrXInc = @divTrunc((csw << 16) + (cdw >> 1), cdw);
        const chrYInc = @divTrunc((csh << 16) + (cdh >> 1), cdh);
        g.hLum = try initFilter(lumXInc, swi, dwi, 1 << 14, algo, 128, 128);
        g.hChr = try initFilter(chrXInc, csw, cdw, 1 << 14, algo, 128, 128);
        g.vLum = try initFilter(lumYInc, shi, dhi, 1 << 12, algo, 128, 128);
        g.vChr = try initFilter(chrYInc, csh, cdh, 1 << 12, algo, 128, 128);

        g.lum = try alloc.alloc(i16, sh * dw + 16);
        g.chrU = try alloc.alloc(i16, g.chrSrcH * g.chrDstW + 16);
        g.chrV = try alloc.alloc(i16, g.chrSrcH * g.chrDstW + 16);
        g.alp = try alloc.alloc(i16, if (g.needAlpha) sh * dw + 16 else 16);
        g.lumNeed = try alloc.alloc(bool, sh);
        g.chrNeed = try alloc.alloc(bool, g.chrSrcH);
        @memset(g.lumNeed, false);
        @memset(g.chrNeed, false);
        for (0..dh) |y| {
            const p: usize = @intCast(g.vLum.pos[y]);
            for (0..g.vLum.size) |j| if (p + j < sh) {
                g.lumNeed[p + j] = true;
            };
        }
        for (0..g.chrDstH) |y| {
            const p: usize = @intCast(g.vChr.pos[y]);
            for (0..g.vChr.size) |j| if (p + j < g.chrSrcH) {
                g.chrNeed[p + j] = true;
            };
        }
        const tw = sw + 64;
        g.tmp16 = try alloc.alloc(u16, tw);
        g.tmpU16 = try alloc.alloc(u16, tw);
        g.tmpV16 = try alloc.alloc(u16, tw);
        g.tmpA16 = try alloc.alloc(u16, tw);
        g.tmpU8 = try alloc.alloc(u8, tw);
        g.tmpV8 = try alloc.alloc(u8, tw);
        return g;
    }

    pub fn deinit(g: *Generic) void {
        g.hLum.deinit();
        g.hChr.deinit();
        g.vLum.deinit();
        g.vChr.deinit();
        alloc.free(g.lum);
        alloc.free(g.chrU);
        alloc.free(g.chrV);
        alloc.free(g.alp);
        alloc.free(g.lumNeed);
        alloc.free(g.chrNeed);
        alloc.free(g.tmp16);
        alloc.free(g.tmpU16);
        alloc.free(g.tmpV16);
        alloc.free(g.tmpA16);
        alloc.free(g.tmpU8);
        alloc.free(g.tmpV8);
        alloc.destroy(g);
    }

    pub fn process(g: *Generic, src: [4][*]const u8, ss: [4]isize, dst: [4][*]u8, ds: [4]isize) void {
        g.horizontal(src, ss);
        g.vertical(dst, ds);
    }

    fn horizontal(g: *Generic, src: [4][*]const u8, ss: [4]isize) void {
        const sf = g.sf;
        const t = rgb2yuv;
        // luma (+alpha)
        for (0..g.sh) |y| {
            if (!g.lumNeed[y]) continue;
            const out = g.lum[y * g.dw ..];
            const s = rowc(src[0], ss[0], y);
            if (isRGB(sf)) {
                const L = rgbLayout(sf);
                for (0..g.sw) |i| {
                    const r: i32 = s[L.bpp * i + L.r];
                    const gg: i32 = s[L.bpp * i + L.g];
                    const b: i32 = s[L.bpp * i + L.b];
                    g.tmp16[i] = @intCast((t[0] * r + t[1] * gg + t[2] * b + (32 << 14) + (1 << 8)) >> 9);
                }
                hScale16(out, g.dw, g.tmp16.ptr, &g.hLum);
                if (g.needAlpha) {
                    for (0..g.sw) |i| g.tmpA16[i] = @as(u16, s[4 * i + 3]) << 6;
                    hScale16(g.alp[y * g.dw ..], g.dw, g.tmpA16.ptr, &g.hLum);
                }
            } else {
                hScale8(out, g.dw, s, &g.hLum);
            }
        }
        if (!g.doChroma) return;
        for (0..g.chrSrcH) |y| {
            if (!g.chrNeed[y]) continue;
            const ou = g.chrU[y * g.chrDstW ..];
            const ov = g.chrV[y * g.chrDstW ..];
            if (isRGB(sf)) {
                const L = rgbLayout(sf);
                const s = rowc(src[0], ss[0], y);
                if (g.chrSrcHSub == 1) {
                    for (0..g.chrSrcW) |i| {
                        const p0 = L.bpp * 2 * i;
                        const p1 = p0 + L.bpp;
                        const r: i32 = @as(i32, s[p0 + L.r]) + s[p1 + L.r];
                        const gg: i32 = @as(i32, s[p0 + L.g]) + s[p1 + L.g];
                        const b: i32 = @as(i32, s[p0 + L.b]) + s[p1 + L.b];
                        g.tmpU16[i] = @truncate(@as(u32, @bitCast((t[3] * r + t[4] * gg + t[5] * b + (256 << 15) + (1 << 9)) >> 10)));
                        g.tmpV16[i] = @truncate(@as(u32, @bitCast((t[6] * r + t[7] * gg + t[8] * b + (256 << 15) + (1 << 9)) >> 10)));
                    }
                } else {
                    for (0..g.chrSrcW) |i| {
                        const r: i32 = s[L.bpp * i + L.r];
                        const gg: i32 = s[L.bpp * i + L.g];
                        const b: i32 = s[L.bpp * i + L.b];
                        g.tmpU16[i] = @truncate(@as(u32, @bitCast((t[3] * r + t[4] * gg + t[5] * b + (256 << 14) + (1 << 8)) >> 9)));
                        g.tmpV16[i] = @truncate(@as(u32, @bitCast((t[6] * r + t[7] * gg + t[8] * b + (256 << 14) + (1 << 8)) >> 9)));
                    }
                }
                hScale16(ou, g.chrDstW, g.tmpU16.ptr, &g.hChr);
                hScale16(ov, g.chrDstW, g.tmpV16.ptr, &g.hChr);
            } else if (sf == m.NV12 or sf == m.NV21) {
                const s = rowc(src[1], ss[1], y);
                for (0..g.chrSrcW) |i| {
                    g.tmpU8[i] = s[2 * i];
                    g.tmpV8[i] = s[2 * i + 1];
                }
                const u = if (sf == m.NV12) g.tmpU8 else g.tmpV8;
                const v = if (sf == m.NV12) g.tmpV8 else g.tmpU8;
                hScale8(ou, g.chrDstW, u.ptr, &g.hChr);
                hScale8(ov, g.chrDstW, v.ptr, &g.hChr);
            } else if (sf == m.GRAY8) {
                @memset(ou[0..g.chrDstW], 128 << 7);
                @memset(ov[0..g.chrDstW], 128 << 7);
            } else {
                hScale8(ou, g.chrDstW, rowc(src[1], ss[1], y), &g.hChr);
                hScale8(ov, g.chrDstW, rowc(src[2], ss[2], y), &g.hChr);
            }
        }
    }

    fn vertical(g: *Generic, dst: [4][*]u8, ds: [4]isize) void {
        const df = g.df;
        if (isRGB(df)) {
            for (0..g.dh) |y| g.outRGB(y, rowm(dst[0], ds[0], y));
            return;
        }
        // planar luma
        for (0..g.dh) |y| {
            vPlanar(g.lum, g.dw, &g.vLum, y, rowm(dst[0], ds[0], y), 1, g.dw);
        }
        if (!g.doChroma) return;
        for (0..g.chrDstH) |y| {
            if (df == m.NV12 or df == m.NV21) {
                const d = rowm(dst[1], ds[1], y);
                const uo: usize = if (df == m.NV12) 0 else 1;
                vPlanar(g.chrU, g.chrDstW, &g.vChr, y, d + uo, 2, g.chrDstW);
                vPlanar(g.chrV, g.chrDstW, &g.vChr, y, d + (1 - uo), 2, g.chrDstW);
            } else {
                vPlanar(g.chrU, g.chrDstW, &g.vChr, y, rowm(dst[1], ds[1], y), 1, g.chrDstW);
                vPlanar(g.chrV, g.chrDstW, &g.vChr, y, rowm(dst[2], ds[2], y), 1, g.chrDstW);
            }
        }
    }

    fn outRGB(g: *Generic, y: usize, d: [*]u8) void {
        const L = rgbLayout(g.df);
        const lf = &g.vLum;
        const cf = &g.vChr;
        const lsz = lf.size;
        const csz = cf.size;
        const lc = lf.coef[y * lsz ..][0..lsz];
        const cc = cf.coef[y * csz ..][0..csz];
        const lp: usize = @intCast(lf.pos[y]);
        const cp: usize = @intCast(cf.pos[y]);
        const W = g.dw;
        const CW = g.chrDstW;
        // select packed1 / packed2 / X like vscale.c
        var mode: u8 = 'X';
        var uvalpha: i32 = 0;
        var yalpha: i32 = 0;
        if (lsz == 1 and csz == 1) {
            mode = '1';
            uvalpha = 0;
        } else if (lsz == 1 and csz == 2 and @as(i32, cc[0]) + cc[1] == 4096 and cc[1] >= 0 and cc[1] <= 4096) {
            mode = '1';
            uvalpha = cc[1];
        } else if (lsz == 2 and csz == 2 and @as(i32, lc[0]) + lc[1] == 4096 and lc[1] >= 0 and lc[1] <= 4096 and @as(i32, cc[0]) + cc[1] == 4096 and cc[1] >= 0 and cc[1] <= 4096) {
            mode = '2';
            yalpha = lc[1];
            uvalpha = cc[1];
        }
        const l0 = g.lum[lp * W ..];
        const l1 = if (lsz > 1) g.lum[(lp + 1) * W ..] else l0;
        const a0 = g.alp[if (g.needAlpha) lp * W else 0 ..];
        const a1 = if (lsz > 1 and g.needAlpha) g.alp[(lp + 1) * W ..] else a0;
        const u0 = g.chrU[cp * CW ..];
        const v0 = g.chrV[cp * CW ..];
        const u1 = if (csz > 1) g.chrU[(cp + 1) * CW ..] else u0;
        const v1 = if (csz > 1) g.chrV[(cp + 1) * CW ..] else v0;
        const hasA = g.needAlpha;
        if (g.fullChr) {
            for (0..W) |i| {
                var Y: i32 = undefined;
                var U: i32 = undefined;
                var V: i32 = undefined;
                var A: i32 = 255;
                if (mode == '1') {
                    Y = @as(i32, l0[i]) * 4;
                    if (uvalpha < 2048) {
                        U = (@as(i32, u0[i]) - (128 << 7)) * 4;
                        V = (@as(i32, v0[i]) - (128 << 7)) * 4;
                    } else {
                        U = (@as(i32, u0[i]) + u1[i] - (128 << 8)) * 2;
                        V = (@as(i32, v0[i]) + v1[i] - (128 << 8)) * 2;
                    }
                    if (hasA) A = clip8((@as(i32, a0[i]) + 64) >> 7);
                } else if (mode == '2') {
                    Y = (@as(i32, l0[i]) * (4096 - yalpha) + @as(i32, l1[i]) * yalpha) >> 10;
                    U = (@as(i32, u0[i]) * (4096 - uvalpha) + @as(i32, u1[i]) * uvalpha - (128 << 19)) >> 10;
                    V = (@as(i32, v0[i]) * (4096 - uvalpha) + @as(i32, v1[i]) * uvalpha - (128 << 19)) >> 10;
                    if (hasA) A = clip8((@as(i32, a0[i]) * (4096 - yalpha) + @as(i32, a1[i]) * yalpha + (1 << 18)) >> 19);
                } else {
                    Y = 1 << 9;
                    U = (1 << 9) - (128 << 19);
                    V = (1 << 9) - (128 << 19);
                    for (0..lsz) |j| Y +%= @as(i32, g.lum[(lp + j) * W + i]) * lc[j];
                    for (0..csz) |j| {
                        U +%= @as(i32, g.chrU[(cp + j) * CW + i]) * cc[j];
                        V +%= @as(i32, g.chrV[(cp + j) * CW + i]) * cc[j];
                    }
                    Y >>= 10;
                    U >>= 10;
                    V >>= 10;
                    if (hasA) {
                        var aa: i32 = 1 << 18;
                        for (0..lsz) |j| aa +%= @as(i32, g.alp[(lp + j) * W + i]) * lc[j];
                        A = clip8(aa >> 19);
                    }
                }
                writeFull(d + i * L.bpp, L, Y, U, V, A);
            }
        } else {
            const npair = (W + 1) >> 1;
            for (0..npair) |i| {
                var Y1: i32 = undefined;
                var Y2: i32 = undefined;
                var U: i32 = undefined;
                var V: i32 = undefined;
                if (mode == '1') {
                    Y1 = (@as(i32, l0[2 * i]) + 64) >> 7;
                    Y2 = (@as(i32, l0[2 * i + 1]) + 64) >> 7;
                    if (uvalpha < 2048) {
                        U = (@as(i32, u0[i]) + 64) >> 7;
                        V = (@as(i32, v0[i]) + 64) >> 7;
                    } else {
                        U = (@as(i32, u0[i]) + u1[i] + 128) >> 8;
                        V = (@as(i32, v0[i]) + v1[i] + 128) >> 8;
                    }
                } else if (mode == '2') {
                    Y1 = (@as(i32, l0[2 * i]) * (4096 - yalpha) + @as(i32, l1[2 * i]) * yalpha) >> 19;
                    Y2 = (@as(i32, l0[2 * i + 1]) * (4096 - yalpha) + @as(i32, l1[2 * i + 1]) * yalpha) >> 19;
                    U = (@as(i32, u0[i]) * (4096 - uvalpha) + @as(i32, u1[i]) * uvalpha) >> 19;
                    V = (@as(i32, v0[i]) * (4096 - uvalpha) + @as(i32, v1[i]) * uvalpha) >> 19;
                } else {
                    Y1 = 1 << 18;
                    Y2 = 1 << 18;
                    U = 1 << 18;
                    V = 1 << 18;
                    for (0..lsz) |j| {
                        Y1 +%= @as(i32, g.lum[(lp + j) * W + 2 * i]) * lc[j];
                        Y2 +%= @as(i32, g.lum[(lp + j) * W + 2 * i + 1]) * lc[j];
                    }
                    for (0..csz) |j| {
                        U +%= @as(i32, g.chrU[(cp + j) * CW + i]) * cc[j];
                        V +%= @as(i32, g.chrV[(cp + j) * CW + i]) * cc[j];
                    }
                    Y1 >>= 19;
                    Y2 >>= 19;
                    U >>= 19;
                    V >>= 19;
                }
                const p1 = y2r.tablePixel(Y1, U, V);
                const p2 = y2r.tablePixel(Y2, U, V);
                const o = d + 2 * i * L.bpp;
                o[L.r] = p1[0];
                o[L.g] = p1[1];
                o[L.b] = p1[2];
                if (L.bpp == 4) o[L.a] = 255;
                if (2 * i + 1 < W) {
                    o[L.bpp + L.r] = p2[0];
                    o[L.bpp + L.g] = p2[1];
                    o[L.bpp + L.b] = p2[2];
                    if (L.bpp == 4) o[L.bpp + L.a] = 255;
                }
            }
        }
    }
};

inline fn clip30(x: i32) i32 {
    if ((x & ~@as(i32, (1 << 30) - 1)) != 0) {
        return (~x >> 31) & ((1 << 30) - 1);
    }
    return x;
}

inline fn writeFull(d: [*]u8, L: RgbL, Yin: i32, U: i32, V: i32, A: i32) void {
    var Y = Yin - full.y_offset;
    Y *%= full.y_coeff;
    Y +%= 1 << 21;
    var R = Y +% V *% full.v2r;
    var G = Y +% V *% full.v2g +% U *% full.u2g;
    var B = Y +% U *% full.u2b;
    if (((R | G | B) & @as(i32, @bitCast(@as(u32, 0xC0000000)))) != 0) {
        R = clip30(R);
        G = clip30(G);
        B = clip30(B);
    }
    d[L.r] = @intCast(@as(u32, @bitCast(R)) >> 22);
    d[L.g] = @intCast(@as(u32, @bitCast(G)) >> 22);
    d[L.b] = @intCast(@as(u32, @bitCast(B)) >> 22);
    if (L.bpp == 4) d[L.a] = @intCast(A);
}

fn hScale8(out: []i16, n: usize, src: [*]const u8, f: *const Filter) void {
    const fs = f.size;
    for (0..n) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val += @as(i32, src[p + j]) * f.coef[i * fs + j];
        out[i] = @intCast(@min(val >> 7, 32767));
    }
}

fn hScale16(out: []i16, n: usize, src: [*]const u16, f: *const Filter) void {
    const fs = f.size;
    for (0..n) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val +%= @as(i32, src[p + j]) * f.coef[i * fs + j];
        out[i] = @intCast(@min(val >> 13, 32767));
    }
}

// yuv2plane1 / yuv2planeX with flat 64 dither, writing every `step` bytes.
fn vPlanar(plane: []const i16, W: usize, f: *const Filter, y: usize, d: [*]u8, step: usize, n: usize) void {
    const fs = f.size;
    const p: usize = @intCast(f.pos[y]);
    const c = f.coef[y * fs ..][0..fs];
    if (fs == 1) {
        const s = plane[p * W ..];
        for (0..n) |i| d[i * step] = clip8((@as(i32, s[i]) + 64) >> 7);
        return;
    }
    for (0..n) |i| {
        var val: i32 = 64 << 12;
        for (0..fs) |j| val +%= @as(i32, plane[(p + j) * W + i]) * c[j];
        d[i * step] = clip8(val >> 19);
    }
}

