fn inputA(d: [*]u16, s: [*]const u8, w: usize) void {
    for (0..w) |i| d[i] = @as(u16, s[4 * i + 3]) << 6;
}

fn inputUV(comptime bpp: usize, comptime ro: usize, comptime go: usize, comptime bo: usize, du: [*]u16, dv: [*]u16, s: [*]const u8, w: usize) void {
