        du[i..][0..VN].* = @as(@Vector(VN, u16), @truncate(@as(@Vector(VN, u32), @bitCast(u))));
        dv[i..][0..VN].* = @as(@Vector(VN, u16), @truncate(@as(@Vector(VN, u32), @bitCast(v))));
    }
    while (i < w) : (i += 1) {
