        const p = std.simd.deinterlace(2 * bpp, x);
        const r: VI = @as(VI, @intCast(p[ro])) + @as(VI, @intCast(p[bpp + ro]));
        const g: VI = @as(VI, @intCast(p[go])) + @as(VI, @intCast(p[bpp + go]));
        const b: VI = @as(VI, @intCast(p[bo])) + @as(VI, @intCast(p[bpp + bo]));
        const k = spl((256 << 15) + (1 << 9));
        const u = (spl(t[3]) * r + spl(t[4]) * g + spl(t[5]) * b + k) >> @splat(10);
        const v = (spl(t[6]) * r + spl(t[7]) * g + spl(t[8]) * b + k) >> @splat(10);
        du[i..][0..VN].* = @as(@Vector(VN, u16), @truncate(@as(@Vector(VN, u32), @bitCast(u))));
        dv[i..][0..VN].* = @as(@Vector(VN, u16), @truncate(@as(@Vector(VN, u32), @bitCast(v))));
