const std = @import("std");
inline fn pmadd(a: @Vector(8, u32), b: @Vector(8, u32)) @Vector(8, i32) {
    const x: @Vector(16, i16) = @bitCast(a);
    const y: @Vector(16, i16) = @bitCast(b);
    const p = @as(@Vector(16, i32), x) * @as(@Vector(16, i32), y);
    const ev = @shuffle(i32, p, undefined, [8]i32{ 0, 2, 4, 6, 8, 10, 12, 14 });
    const od = @shuffle(i32, p, undefined, [8]i32{ 1, 3, 5, 7, 9, 11, 13, 15 });
    return ev + od;
}
inline fn gath(src: [*]const u8, off: @Vector(8, i32)) @Vector(8, u32) {
    var v: @Vector(8, u32) = undefined;
    inline for (0..8) |k| v[k] = @as(*align(1) const u32, @ptrCast(src + @as(usize, @intCast(off[k])))).*;
    return v;
}
// variant A: separate stores per pass
export fn kA(acc: [*]i32, n: usize, src: [*]const u8, pos: [*]const i32, cpair: [*]const u32, jj: usize) void {
    var i: usize = 0;
    while (i + 8 <= n) : (i += 8) {
        const idx: @Vector(8, i32) = pos[i..][0..8].*;
        const off = idx + @as(@Vector(8, i32), @splat(@intCast(4 * jj)));
        const cp: @Vector(8, u32) = cpair[i..][0..8].*;
        const a: @Vector(8, i32) = acc[i..][0..8].*;
        acc[i..][0..8].* = a +% pmadd(gath(src, off), cp);
    }
}
// variant B: two pmadds with min trick
export fn kB(out: [*]i16, n: usize, src: [*]const u8, pos: [*]const i32, cpair: [*]const u32) void {
    var i: usize = 0;
    while (i + 8 <= n) : (i += 8) {
        const idx: @Vector(8, i32) = pos[i..][0..8].*;
        const c0: @Vector(8, u32) = cpair[2 * i ..][0..8].*;
        const c1: @Vector(8, u32) = cpair[2 * i + 8 ..][0..8].*;
        const g0 = gath(src, idx);
        const g1 = gath(src, idx + @as(@Vector(8, i32), @splat(4)));
        const x0: @Vector(16, i16) = @bitCast(g0);
        const x1: @Vector(16, i16) = @bitCast(g1);
        const y0: @Vector(16, i16) = @bitCast(c0);
        const y1: @Vector(16, i16) = @bitCast(c1);
        const p = @as(@Vector(16, i32), x0) * @as(@Vector(16, i32), y0) + @as(@Vector(16, i32), x1) * @as(@Vector(16, i32), y1);
        const ev = @shuffle(i32, p, undefined, [8]i32{ 0, 2, 4, 6, 8, 10, 12, 14 });
        const od = @shuffle(i32, p, undefined, [8]i32{ 1, 3, 5, 7, 9, 11, 13, 15 });
        const r = @min((ev + od) >> @splat(13), @as(@Vector(8, i32), @splat(32767)));
        out[i..][0..8].* = @as(@Vector(8, i16), @truncate(r));
    }
}
