            var Ya: VH = undefined;
            var Yb: VH = undefined;
            switch (sel.mode) {
                '1' => {
                    Ya = ldH(l0 + i);
                    Yb = ldH(l0 + i + HN);
                },
                '2' => {
                    Ya = vBlendH(l0, l1, ya8, i);
                    Yb = vBlendH(l0, l1, ya8, i + HN);
                },
                else => {
                    Ya = vSumH(g.lum.ptr, W, lp, lc4[0..lsz], i);
                    Yb = vSumH(g.lum.ptr, W, lp, lc4[0..lsz], i + HN);
                },
            }
            const Ud = std.simd.interlace(.{ U, U });
            const Vd = std.simd.interlace(.{ V, V });
            const Ua: VH = std.simd.extract(Ud, 0, HN);
            const Ub: VH = std.simd.extract(Ud, HN, HN);
            const Va: VH = std.simd.extract(Vd, 0, HN);
            const Vb: VH = std.simd.extract(Vd, HN, HN);
            const qa = yuv15ToRgb(Ya, Ua, Va);
            const qb = yuv15ToRgb(Yb, Ub, Vb);
            storeRGB(L, d + i * L.bpp, HN, qa[0], qa[1], qa[2], @splat(255));
            storeRGB(L, d + (i + HN) * L.bpp, HN, qb[0], qb[1], qb[2], @splat(255));
        }
    }
    if (i < W) {
        // exact scalar path for the tail
        if (full_chr) g.outFullTail(f, y, d, i) else g.outHalfTail(f, y, d, i / 2);
    }
}
